import{_ as e,o as t,c as n,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Troubleshooting: Login & Accounts","description":"Resolve issues related to Google Sign-In, session management, and account initialization.","frontmatter":{"title":"Troubleshooting: Login & Accounts","description":"Resolve issues related to Google Sign-In, session management, and account initialization."},"headers":[],"relativePath":"support/troubleshooting_auth.md","filePath":"support/troubleshooting_auth.md"}'),r={name:"support/troubleshooting_auth.md"};function i(s,o,l,u,c,g){return t(),n("div",null,[...o[0]||(o[0]=[a('<h1 id="troubleshooting-login-accounts" tabindex="-1">Troubleshooting: Login &amp; Accounts <a class="header-anchor" href="#troubleshooting-login-accounts" aria-label="Permalink to &quot;Troubleshooting: Login &amp; Accounts&quot;">​</a></h1><p>Welcome to the Sanjeev AI account support page. Our platform uses Google Sign-In for secure authentication.</p><h2 id="_1-google-sign-in-popup-blocked" tabindex="-1">1. Google Sign-In Popup Blocked <a class="header-anchor" href="#_1-google-sign-in-popup-blocked" aria-label="Permalink to &quot;1. Google Sign-In Popup Blocked&quot;">​</a></h2><p><strong>Symptom:</strong> You click &quot;Sign in with Google&quot;, but nothing happens. <strong>Cause:</strong> Your browser has blocked the popup window required by Firebase Authentication. <strong>Solution:</strong></p><ol><li>Look at the right side of your browser&#39;s URL bar for a small icon indicating a blocked popup (often a red &#39;x&#39; or a window icon).</li><li>Click the icon and select <strong>Always allow popups and redirects from sanjeev.ai</strong>.</li><li>Refresh the page and try logging in again.</li></ol><h2 id="_2-endless-loading-screen-after-login" tabindex="-1">2. Endless Loading Screen After Login <a class="header-anchor" href="#_2-endless-loading-screen-after-login" aria-label="Permalink to &quot;2. Endless Loading Screen After Login&quot;">​</a></h2><p><strong>Symptom:</strong> You successfully authenticate with Google, but the app gets stuck on a spinning loading screen instead of taking you to the dashboard. <strong>Cause:</strong> The backend <code>createUserDocument</code> Cloud Function may have failed to initialize your Firestore profile, or your browser cached a stale authentication state. <strong>Solution:</strong></p><ol><li><strong>Clear cache:</strong> Press <code>Ctrl + Shift + R</code> (Windows) or <code>Cmd + Shift + R</code> (Mac) to hard refresh the page.</li><li><strong>Re-authenticate:</strong> Log out completely by visiting <code>sanjeev.ai/logout</code> directly, then log back in.</li><li>If the issue persists, contact support with your Google account email so we can manually provision your user document.</li></ol><h2 id="_3-not-authorized-or-403-errors" tabindex="-1">3. &quot;Not Authorized&quot; or 403 Errors <a class="header-anchor" href="#_3-not-authorized-or-403-errors" aria-label="Permalink to &quot;3. &quot;Not Authorized&quot; or 403 Errors&quot;">​</a></h2><p><strong>Symptom:</strong> You are logged in, but you see &quot;403 PERMISSION_DENIED&quot; errors when trying to load projects or generate media. <strong>Cause:</strong> Your session token has expired, or you are trying to access a project ID that belongs to another user. <strong>Solution:</strong></p><ol><li>Ensure you are signed in with the correct Google account. (If you use multiple accounts, you may have switched).</li><li>Sign out and sign back in to force a refresh of your Firebase session token.</li></ol><h2 id="_4-account-deletion" tabindex="-1">4. Account Deletion <a class="header-anchor" href="#_4-account-deletion" aria-label="Permalink to &quot;4. Account Deletion&quot;">​</a></h2><p>Currently, to delete your Sanjeev AI account and wipe all associated project data and media, you must contact support directly. Automatic self-service deletion is on our roadmap.</p>',13)])])}const p=e(r,[["render",i]]);export{h as __pageData,p as default};
